<?php
namespace App\Http\Controllers\Procurement;use App\Http\Controllers\Controller;use App\Models\{Account,GoodsReceivedNote,PurchaseOrder,Supplier,SupplierInvoice};use App\Services\Accounting\AccountingService;use App\Services\Procurement\ProcurementService;use Illuminate\Http\Request;
class SupplierInvoiceController extends Controller{public function index(){ $p=auth()->user()->property_id;return view('procurement.invoices.index',['rows'=>SupplierInvoice::with(['supplier','payments'])->where('property_id',$p)->latest()->paginate(30),'suppliers'=>Supplier::where('property_id',$p)->get(),'orders'=>PurchaseOrder::where('property_id',$p)->get(),'grns'=>GoodsReceivedNote::where('property_id',$p)->where('status','posted')->get()]);}public function store(Request $r){$d=$r->validate(['supplier_id'=>'required|integer','purchase_order_id'=>'nullable|integer','goods_received_note_id'=>'nullable|integer','invoice_number'=>'required|max:100','invoice_date'=>'required|date','due_date'=>'nullable|date','subtotal'=>'required|numeric|min:0','tax_amount'=>'nullable|numeric|min:0','notes'=>'nullable']);$d['property_id']=auth()->user()->property_id;$d['tax_amount']=$d['tax_amount']??0;$d['total_amount']=$d['subtotal']+$d['tax_amount'];$d['created_by']=auth()->id();$invoice=SupplierInvoice::create($d);if(Account::where('property_id',$d['property_id'])->where('code','2000')->exists()){$je=app(AccountingService::class)->postSupplierInvoice($d['property_id'],$invoice->id,(float)$invoice->subtotal,(float)$invoice->tax_amount,auth()->id());$invoice->update(['journal_entry_id'=>$je->id]);}return back()->with('success','Supplier invoice recorded.');}public function pay(Request $r,SupplierInvoice $invoice,ProcurementService $svc){abort_unless($invoice->property_id===auth()->user()->property_id,403);$d=$r->validate(['amount'=>'required|numeric|min:.01','method'=>'required|in:cash,bank_transfer,cheque,mtn_momo,airtel_money,other','payment_date'=>'required|date','reference'=>'required|max:80','external_reference'=>'nullable|max:100','notes'=>'nullable']);$svc->payInvoice($invoice,$d,auth()->id());return back()->with('success','Supplier payment recorded.');}}